// Converts a Telegram update into chatInput + sessionId and runs the deterministic emergency screen.
// The emergency screen runs BEFORE the AI so emergency routing never depends on the model.
const update = $input.first().json;
const msg = update.message;

// Ignore anything that is not a private 1-to-1 chat (e.g. the bot being added to a group).
if (!msg || !msg.chat || msg.chat.type !== 'private') {
  return [];
}

const hasText = typeof msg.text === 'string' && msg.text.trim().length > 0;
const raw = hasText
  ? msg.text.trim()
  : (msg.caption ? String(msg.caption) : '[non-text message]');
const t = raw.toLowerCase();

const patterns = [
  /(can'?t|cannot|can not|unable to|difficult(y)?|trouble|hard to|struggling to|problem)\s*(to\s+)?(breath|breathe|breathing|swallow|swallowing)/,
  /(short of breath|choking|gasping)/,
  /uncontrolled bleeding|won'?t stop bleeding|will not stop bleeding|bleeding (a lot|heavily|badly|non.?stop)|bleeding (that )?(has )?not stopped/,
  /(swelling|swollen).{0,40}(spreading|spread|neck|throat|eye|face)|(spreading|neck|throat).{0,40}(swelling|swollen)/,
  /(collapse|collapsed|unconscious|passed out|blacked out)/,
  /(jaw|facial|face).{0,30}(broken|fracture|fractured|trauma|accident|injury)/
];

const emergency = patterns.some(p => p.test(t));

return [{ json: {
  chatInput: raw,
  sessionId: String(msg.chat.id),
  emergency
}}];

parameters.message:
=HIGH PRIORITY

