// Deterministic opening-hours check (Nigeria time, WAT = UTC+1, no daylight saving).
let q = query;
if (typeof q === 'string') {
  try { q = JSON.parse(q); }
  catch (e) { return 'INVALID: send input as JSON like {"start":"2026-11-05T10:00:00+01:00","end":"2026-11-05T10:30:00+01:00"}'; }
}
const s = new Date(q.start);
const e = new Date(q.end);
if (isNaN(s) || isNaN(e)) return 'INVALID: start or end is not a valid ISO 8601 date-time.';
if (e <= s) return 'INVALID: end must be after start.';

const MIN_LEAD_MS = 60 * 60 * 1000; // minimum booking lead time: 1 hour (clinic to confirm)
if (s.getTime() < Date.now() + MIN_LEAD_MS) return 'INVALID: the appointment must start at least 1 hour from now.';

const OFFSET = 60 * 60 * 1000;
const ws = new Date(s.getTime() + OFFSET);
const we = new Date(e.getTime() + OFFSET);
if (ws.getUTCDate() !== we.getUTCDate()) return 'INVALID: the appointment must start and end on the same day.';

const hours = { 0: null, 1: [8, 18], 2: [8, 18], 3: [8, 18], 4: [8, 18], 5: [8, 18], 6: [8, 16] };
const h = hours[ws.getUTCDay()];
if (!h) return 'INVALID: the clinic is closed on Sundays.';

const startMin = ws.getUTCHours() * 60 + ws.getUTCMinutes();
const endMin = we.getUTCHours() * 60 + we.getUTCMinutes();
if (startMin < h[0] * 60 || endMin > h[1] * 60) {
  return 'INVALID: outside opening hours. On this day the clinic is open ' + h[0] + ':00 to ' + h[1] + ':00 (24-hour clock).';
}
return 'VALID: within regular opening hours. Public holidays are not checked here.';
